/// <summary>
/// Map data fields to virtual fields
/// CB871_CB872 Sales returns
/// </summary>
public void postLoad()
{
    changecompany(this.DataAreaId)
    {
        this.METUnitInShipCase = METCalcWMSFactor::construct().getUnitinShipCaseFactor(this.ItemNumber, this.METSalesLineInventDimId);
    }

    next postLoad();
}

/// <summary>
/// Finds record buffer for data source and return
/// </summary>
/// <param name = "_entityCtx">Entity context</param>
/// <param name = "_dataSourceCtx">Data source runtime context</param>
/// <returns>Record buffer associated with data source</returns>
public Common findEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    Common ret = next findEntityDataSource(_entityCtx, _dataSourceCtx);

    if (_dataSourceCtx.name() == dataEntityDataSourceStr(ReturnOrderLineV2Entity, METSalesLine))
    {
        ret = METSalesLine::find(this.RecId);
    }

    return ret;
}

/// <summary>
/// CoC method for InsertEntityDataSource method
/// </summary>
/// <param name = "_entityCtx">Param of type DataEntityRuntimeContext</param>
/// <param name = "_dataSourceCtx">Param of type DataEntityDataSourceRuntimeContext</param>
/// <returns>true of false</returns>
public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    if (_dataSourceCtx.name() == dataEntityDataSourceStr(ReturnOrderLineV2Entity, METSalesLine))
    {
        SalesLine metSalesLineStd   = _entityCtx.getRuntimeContextByName(dataEntityDataSourceStr(ReturnOrderLineV2Entity, SalesLine)).getBuffer();
        _dataSourceCtx.setBuffer(METSalesLine::find(metSalesLineStd.RecId, true));
        _dataSourceCtx.setDatabaseOperation(DataEntityDatabaseOperation::Update);

        this.mapEntityToDataSource(_entityCtx, _dataSourceCtx);
    }

    boolean ret = next insertEntityDataSource(_entityCtx, _dataSourceCtx);

    return ret;
}

/// <summary>
/// MPJ_24809 Returns Claims
/// </summary>
public void insert()
{
    CustInvoiceTrans    metCustInvoiceTransStd;
    select firstonly metCustInvoiceTransStd
        where metCustInvoiceTransStd.InvoiceId  == this.METInvoiceNumber &&
              metCustInvoiceTransStd.LineNum    == this.METInvoiceLineNumber;
    if(metCustInvoiceTransStd)
    {
        if(metCustInvoiceTransStd.SalesUnit == this.SalesUnitSymbol)
        {
            this.SalesPrice         = metCustInvoiceTransStd.SalesPrice;
            this.SalesUnitSymbol    = metCustInvoiceTransStd.SalesUnit;
        }
        else //MPJ-35503-Broken cases
        {
            this.METBrokenCaseForClaims = NoYes::Yes;
            if(metCustInvoiceTransStd.SalesUnit == this.SalesUnitSymbol)
            {
                this.SalesPrice             = metCustInvoiceTransStd.SalesPrice;
            }
            else
            {
                this.SalesPrice             = metCustInvoiceTransStd.SalesPrice/UnitOfMeasureConverter::convert(1,
               UnitOfMeasure::unitOfMeasureIdBySymbol(metCustInvoiceTransStd.SalesUnit),
               UnitOfMeasure::unitOfMeasureIdBySymbol(this.SalesUnitSymbol),
               NoYes::Yes,
               InventTable::itemProduct(this.ItemNumber),
               NoYes::Yes);

            }
        }
        this.LineAmount             = -(metCustInvoiceTransStd.LineAmount);
        this.ReturnSiteId           = metCustInvoiceTransStd.inventSiteId();
        this.ReturnWarehouseId      = metCustInvoiceTransStd.inventLocationId();
        this.ReturnInventoryLotId   = metCustInvoiceTransStd.InventTransId;            
        /* this.METInventTransIdReturn = metCustInvoiceTransStd.InventTransId; may need later
        //Catch weight item
        if (InventTable::find(this.ItemNumber).Product().PdsCWProduct)
        {
            this.METPdsCWQty=-1;
        } */
    }
    next insert();
}

/// <summary>
/// Map entity to datasource
/// </summary>
/// <param name = "_entityCtx">DataEntityRuntimeContext</param>
/// <param name = "_dataSourceCtx">DataEntityDataSourceRuntimeContext</param>
public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    next mapEntityToDataSource(_entityCtx, _dataSourceCtx);

    switch (_dataSourceCtx.name())
    {
        case dataEntityDataSourceStr(ReturnOrderLineV2Entity, SalesLine):
            if (_entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Insert
                || _entityCtx.getDatabaseOperation() == DataEntityDatabaseOperation::Update)
            {
                SalesLine salesLine = _dataSourceCtx.getBuffer() as SalesLine;

                CustInvoiceTrans    metCustInvoiceTransStd;

                select firstonly SalesId, LineAmount from metCustInvoiceTransStd
                    where metCustInvoiceTransStd.InvoiceId  == this.METInvoiceNumber 
                    && metCustInvoiceTransStd.LineNum    == this.METInvoiceLineNumber;                    

                if (metCustInvoiceTransStd.SalesId && this.METInvoiceNumber)
                {
                    SalesLine salesLineLoc;

                    select firstonly LineDisc, SalesPrice, RecId from salesLineLoc
                        where salesLineLoc.SalesId == metCustInvoiceTransStd.salesid
                        && salesLineLoc.ItemId == this.ItemNumber  
                        && salesLineLoc.LineNum ==  this.METInvoiceLineNumber;

                    if (salesLineLoc.RecId)
                    {
                        salesLine.LineDisc = salesLineLoc.LineDisc;
                        salesLine.SalesPrice = salesLineLoc.SalesPrice;
                        SalesLine.lineAmount = -(metCustInvoiceTransStd.LineAmount);
                    }                    
                }

                // Fix for Bug 344375 - blank line number
                if (!salesLine.LineNum)
                {
                    SalesLine salesLineLoc;
                    select firstonly SalesId from salesLineLoc where salesLineLoc.SalesId == this.ReturnOrderNumber;
                    salesLine.LineNum = this.LineCreationSequenceNumber ? this.LineCreationSequenceNumber : salesLineLoc.nextLineCreationSequence();
                }
            }
    }
}

/// <summary>
/// Method to update the return disposition code on the sales line if it has changed
/// </summary>
public void update()
{
    SalesLine   salesline = SalesLine::findInventTransId(this.ReturnInventoryLotId);

    next update();

    if (salesline.ReturnDispositionCodeId != this.ReturnDispositionCode)
    {
        this.modifiedField(fieldNum(salesline, ReturnDispositionCodeId));
    }


}
